-- ============================================================
-- Snowflake: full setup (database, schema, tables, data)
-- IMPORTANT: Run the WHOLE script in one worksheet using "Run All"
-- (the dropdown arrow next to the Run button), not just the
-- selected statement or the first statement. Running only part
-- of this script is the most common cause of "object does not
-- exist" errors on tables like CUSTOMERS.
-- ============================================================

-- Use your own warehouse name here if different from the default
USE WAREHOUSE COMPUTE_WH;
USE ROLE ACCOUNTADMIN;
CREATE DATABASE IF NOT EXISTS BANK_DB;
CREATE SCHEMA IF NOT EXISTS BANK_DB.PUBLIC;
USE DATABASE BANK_DB;
USE SCHEMA PUBLIC;

-- Clean up (children first so foreign keys don't block the drops)
DROP TABLE IF EXISTS loan_payments;
DROP TABLE IF EXISTS cards;
DROP TABLE IF EXISTS transactions;
DROP TABLE IF EXISTS loans;
DROP TABLE IF EXISTS accounts;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS transaction_types;
DROP TABLE IF EXISTS account_types;
DROP TABLE IF EXISTS branches;
DROP TABLE IF EXISTS customers;

CREATE TABLE customers (
    customer_id INT PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    date_of_birth DATE,
    gender VARCHAR(10),
    phone VARCHAR(15),
    email VARCHAR(100),
    city VARCHAR(50),
    state VARCHAR(50),
    occupation VARCHAR(100),
    customer_since DATE,
    customer_status VARCHAR(20)
);
CREATE TABLE branches (
    branch_id INT PRIMARY KEY,
    branch_name VARCHAR(100),
    city VARCHAR(50),
    state VARCHAR(50),
    branch_manager_id INT,
    opening_date DATE
);
CREATE TABLE account_types (
    account_type_id INT PRIMARY KEY,
    account_type_name VARCHAR(50),
    minimum_balance DECIMAL(15,2),
    interest_rate DECIMAL(5,2)
);
CREATE TABLE accounts (
    account_id BIGINT PRIMARY KEY,
    customer_id INT,
    branch_id INT,
    account_type_id INT,
    account_number VARCHAR(20),
    opening_date DATE,
    balance DECIMAL(15,2),
    account_status VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (branch_id) REFERENCES branches(branch_id),
    FOREIGN KEY (account_type_id) REFERENCES account_types(account_type_id)
);
CREATE TABLE transaction_types (
    transaction_type_id INT PRIMARY KEY,
    transaction_type_name VARCHAR(50),
    transaction_category VARCHAR(50)
);
CREATE TABLE transactions (
    transaction_id BIGINT PRIMARY KEY,
    account_id BIGINT,
    transaction_type_id INT,
    transaction_date TIMESTAMP,
    amount DECIMAL(15,2),
    transaction_mode VARCHAR(30),
    merchant_name VARCHAR(100),
    reference_number VARCHAR(50),
    transaction_status VARCHAR(20),
    balance_after_transaction DECIMAL(15,2),
    FOREIGN KEY (account_id) REFERENCES accounts(account_id),
    FOREIGN KEY (transaction_type_id) REFERENCES transaction_types(transaction_type_id)
);
CREATE TABLE loans (
    loan_id BIGINT PRIMARY KEY,
    customer_id INT,
    branch_id INT,
    loan_type VARCHAR(50),
    loan_amount DECIMAL(15,2),
    interest_rate DECIMAL(5,2),
    tenure_months INT,
    start_date DATE,
    end_date DATE,
    loan_status VARCHAR(20),
    outstanding_amount DECIMAL(15,2),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);
CREATE TABLE loan_payments (
    payment_id BIGINT PRIMARY KEY,
    loan_id BIGINT,
    payment_date DATE,
    payment_amount DECIMAL(15,2),
    principal_amount DECIMAL(15,2),
    interest_amount DECIMAL(15,2),
    payment_status VARCHAR(20),
    FOREIGN KEY (loan_id) REFERENCES loans(loan_id)
);
CREATE TABLE cards (
    card_id BIGINT PRIMARY KEY,
    customer_id INT,
    account_id BIGINT,
    card_type VARCHAR(20),
    card_network VARCHAR(20),
    issue_date DATE,
    expiry_date DATE,
    credit_limit DECIMAL(15,2),
    card_status VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id),
    FOREIGN KEY (account_id) REFERENCES accounts(account_id)
);
CREATE TABLE employees (
    employee_id INT PRIMARY KEY,
    branch_id INT,
    employee_name VARCHAR(100),
    job_title VARCHAR(50),
    hire_date DATE,
    salary DECIMAL(12,2),
    employee_status VARCHAR(20),
    FOREIGN KEY (branch_id) REFERENCES branches(branch_id)
);

-- ===================== DATA =====================
-- account_types: 5 rows

-- employees: 2000 rows

-- branches: 2000 rows

-- customers: 2000 rows

-- transaction_types: 8 rows

-- accounts: 2000 rows

-- transactions: 2000 rows

-- loans: 2000 rows

-- loan_payments: 2000 rows

-- cards: 2000 rows

-- Reaffirm context before verifying (in case the session drifted)
USE DATABASE BANK_DB;
USE SCHEMA PUBLIC;

-- Verify row counts
SELECT 'customers' t, COUNT(*) n FROM customers UNION ALL SELECT 'branches',COUNT(*) FROM branches
UNION ALL SELECT 'account_types',COUNT(*) FROM account_types UNION ALL SELECT 'accounts',COUNT(*) FROM accounts
UNION ALL SELECT 'transaction_types',COUNT(*) FROM transaction_types UNION ALL SELECT 'transactions',COUNT(*) FROM transactions
UNION ALL SELECT 'loans',COUNT(*) FROM loans UNION ALL SELECT 'loan_payments',COUNT(*) FROM loan_payments
UNION ALL SELECT 'cards',COUNT(*) FROM cards UNION ALL SELECT 'employees',COUNT(*) FROM employees;